/**
 * Kumva SendMessage Node
 * Sends SMS/IVR for OUTBOUND mode and captures sessionId from Africa's Talking
 */

module.exports = function(RED) {
  const AfricasTalkingService = require('kumva-insights/utils/africastalking');
  const SessionManager = require('kumva-insights/utils/session-manager');
  const DataStorage = require('kumva-insights/utils/data-storage');
  const ConfigManager = require('kumva-insights/utils/config-manager');
  const helpers = require('kumva-insights/utils/helpers');

  let globalSessionManager = null;
  let globalDataStorage = null;

  async function initializeGlobals() {
    if (!globalSessionManager) {
      const configManager = new ConfigManager();
      globalSessionManager = new SessionManager(configManager.getRedisConfig());
      await globalSessionManager.initialize();
      globalDataStorage = new DataStorage(configManager.getStoragePath());
    }
    return { sessionManager: globalSessionManager, dataStorage: globalDataStorage };
  }

  function KumvaSendMessageNode(config) {
    RED.nodes.createNode(this, config);
    const node = this;

    node.on('input', async function(msg) {
      try {
        // Get credentials from Start Campaign
        const credentials = msg.credentials;
        if (!credentials?.username || !credentials?.apiKey) {
          node.status({ fill: 'red', shape: 'ring', text: 'No credentials' });
          return node.error('No Africa\'s Talking credentials');
        }

        const phoneNumber = msg.phoneNumber;
        if (!phoneNumber || !helpers.isValidPhoneNumber(phoneNumber)) {
          return node.error(`Invalid phone number: ${phoneNumber}`);
        }

        const { sessionManager, dataStorage } = await initializeGlobals();
        const initiationMode = msg.initiationMode || 'outbound';
        const campaignType = msg.campaignData?.campaignType || 'sms';

        // ============================================
        // OUTBOUND MODE: We initiate SMS or voice call
        // ============================================
        if (initiationMode === 'outbound') {
          
          const atService = new AfricasTalkingService(credentials);
          let result = null;

          if (campaignType === 'sms') {
            // Send SMS
            node.status({ fill: 'blue', shape: 'dot', text: 'Sending SMS...' });
            
            const messageContent = msg.initialMessage || '';
            const shortCode = msg.campaignData?.shortCode || null;

            result = await atService.sendSMS(phoneNumber, messageContent, shortCode);
            console.log('SMS send result: ', JSON.stringify(result));
            if (!result.success) {
              throw new Error(`SMS failed: ${result.error}`);
            }

            node.log(`SMS sent to ${phoneNumber}, messageId: ${result.messageId}`);

            // For SMS: sessionId comes later when user replies (in webhook)
            const outputMsg = {
              ...msg,
              messageId: result.messageId,
              messageStatus: 'sent',
              awaitingSessionId: true, // Will get sessionId from webhook when user replies
              _kumva: {
                ...msg._kumva,
                messageId: result.messageId,
                sentAt: new Date().toISOString(),
                awaitingSessionId: true
              }
            };

            node.status({ fill: 'yellow', shape: 'dot', text: 'Awaiting response' });
            node.send(outputMsg);

          } else if (campaignType === 'voice') {
            // Make IVR call
            node.status({ fill: 'blue', shape: 'dot', text: 'Initiating call...' });
            
            const callerId = msg.campaignData?.callerId || null;
            const ttsText = msg.initialMessage || 'Welcome to our service';

            result = await atService.sendIVR(phoneNumber, {
              ttsText: ttsText,
              callerId: callerId
            });

            if (!result.success) {
              throw new Error(`IVR call failed: ${result.error}`);
            }

            const sessionId = result.sessionId;
            node.log(`IVR call initiated: ${sessionId}`);

            // For voice: We have sessionId immediately from Africa's Talking
            // Create session now
            const sessionData = {
              sessionId: sessionId,
              phoneNumber: phoneNumber,
              campaignId: msg.campaignId,
              campaignType: 'voice',
              initiationMode: 'outbound',
              status: 'active',
              createdAt: new Date().toISOString(),
              contactData: msg.contactData || {},
              credentials: credentials,
              webhookUrl: msg.webhookUrl
            };

            const timeoutSeconds = msg.campaignData?.sessionTimeout || 3600;
            await sessionManager.createSession(sessionId, sessionData, timeoutSeconds);

            node.log(`Session created: ${sessionId}`);

            const outputMsg = {
              ...msg,
              sessionId: sessionId,
              messageStatus: 'sent',
              callInitiated: true,
              _kumva: {
                ...msg._kumva,
                sessionId: sessionId,
                sentAt: new Date().toISOString(),
                hasSessionId: true
              }
            };

            node.status({ fill: 'green', shape: 'dot', text: `Session: ${sessionId.substring(0, 12)}...` });
            node.send(outputMsg);
          }

        // ============================================
        // INBOUND MODE: User calls/texts us
        // ============================================
        } else if (initiationMode === 'inbound') {
          // For inbound, we don't send anything
          // Just pass through and wait for user to contact
          // sessionId will come from webhook callback

          const outputMsg = {
            ...msg,
            awaitingInboundContact: true,
            messageStatus: 'ready',
            _kumva: {
              ...msg._kumva,
              inboundReady: true,
              readyAt: new Date().toISOString()
            }
          };

          node.status({ fill: 'yellow', shape: 'dot', text: 'Waiting for user contact' });
          node.send(outputMsg);
        }

      } catch (error) {
        node.error(`SendMessage: ${error.message}`);
        node.status({ fill: 'red', shape: 'ring', text: 'Error' });
        
        msg.messageStatus = 'failed';
        msg.messageError = error.message;
        node.send(msg);
      }
    });

    node.status({ fill: 'yellow', shape: 'ring', text: 'Ready' });
  }

  RED.nodes.registerType('kumva-send-message', KumvaSendMessageNode);
};